Given the root of a Binary Search Tree (BST) and two integers low and high, return all node values that lie in the inclusive range [low, high] in ascending order.Examples:Input: root = [17, 4, 18, 2, 9, N, N], l = 4, h = 17Output: [4, 9, 17]Explanation: The BST nodes whose values lie in the range [4, 17] are 4, 9, and 17. Hence the result is returned as [4, 9, 17].Input: root = [16, 7, 20, 1, 10, N, N], l = 13, h = 23Output: [16, 20]Explanation: The nodes in the range [13, 23] are 16 and 20. Hence the result is returned as [16, 20].Try It YourselfTable of Content[Naive Approach] Inorder Traversal - O(n) Time and O(n) Space[Optimal Approach] Pruned Inorder Traversal - O(n) Time and O(n) Space[Expected Approach] Pruned Morris Traversal - O(n) Time and O(1) Space[Naive Approach] Inorder Traversal - O(n) Time and O(n) SpacePerform inorder traversal of BST to get nodes in sorted order. Collect nodes whose values lie within [low, high] range.Perform inorder traversal on BSTAt each node, check if data is between low and highIf yes, add to answer array
            C++

    #include <iostream>
#include <vector>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

void inorder(Node* root, int low, int high, vector<int>& ans) {
    if (root == nullptr) return;

    // Visit left subtree
    inorder(root->left, low, high, ans);

    // Check current node
    if (root->data >= low && root->data <= high) {
        ans.push_back(root->data);
    }

    // Visit right subtree
    inorder(root->right, low, high, ans);
}

vector<int> nodesInRange(Node* root, int low, int high) {
    vector<int> ans;
    inorder(root, low, high, ans);
    return ans;
}

int main() {
    Node* root = new Node(22);
    root->left = new Node(12);
    root->right = new Node(30);
    root->left->left = new Node(8);
    root->left->right = new Node(20);

    int low = 10, high = 22;

    vector<int> ans = nodesInRange(root, low, high);

    for (int x : ans) {
        cout << x << " ";
    }

    return 0;
}


