        }

        // Visit right subtree
        inorder(root.right, low, high, ans);
    }

    static ArrayList<Integer> nodesInRange(Node root, int low, int high) {
        ArrayList<Integer> ans = new ArrayList<>();

        inorder(root, low, high, ans);

        return ans;
    }

